#pragma once
#include "MyLib/mylib_export.h" // MYLIB_EXPORT — generated by generate_export_header() at configure time

#include <cstdint>

namespace mymath {

// Results are 64-bit: any sum, difference or product of two ints fits, so these can't overflow
// (signed overflow is undefined behavior — the fuzzer in fuzz/ found it in the int versions).
MYLIB_EXPORT auto add(int a, int b) -> std::int64_t;
MYLIB_EXPORT auto subtract(int a, int b) -> std::int64_t;
MYLIB_EXPORT auto multiply(int a, int b) -> std::int64_t;
MYLIB_EXPORT auto divide(double a, double b) -> double;

}; // namespace mymath
